-- Generated by execution/homework_sql.ts from docs/homework-2026-27/final/qaidah-hw4.json.
-- Loads homework 304 for 2026/27. Review, then apply with execution/apply_migration.ts.
-- Idempotent: re-running replaces the same papers again.

do $guard$ begin
  if exists (select 1 from submissions s join homeworks h on h.id = s.homework_id
             join auth.users u on u.id = s.student_id
             where h.number in (304) and coalesce(u.email, '') not like '%@bsms-demo.test') then
    raise exception 'a real student has work on a homework this load replaces; stop and ask';
  end if;
end $guard$;

-- Demo work on the replaced papers (answers, voice notes, attempts cascade).
delete from submissions where homework_id in (select id from homeworks where number in (304));
delete from questions where homework_id in (select id from homeworks where number in (304));

-- ── Homework 304: Madd Aṣlī Practice (4 marks, 4 questions)
insert into homeworks (number, title, series, total_marks, is_graded, week_id, due_at, course_id, ordinal)
select 304, $q$Madd Aṣlī Practice$q$, 'qaidah', 4, true, w.id, w.due_at, c.id, 4
  from weeks w, courses c where w.term_id = 1 and w.number = 4 and c.key = 'qaidah'
on conflict (number) do update set title = excluded.title, series = excluded.series, total_marks = excluded.total_marks,
  is_graded = true, course_id = excluded.course_id, ordinal = excluded.ordinal;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 1, 'text', 'manual', $q$Madd with alif. Read the following words and record yourself. Take your time, and hold each long vowel for two counts, no more and no less.
The letters in red carry the madd. In the last picture the alif is written small above the letter.$q$, 1, false, true, null, null, false
  from homeworks where number = 304;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 2, 'text', 'manual', $q$Madd with yā'. Read the following words and record yourself. Take your time, and hold each long vowel for two counts, no more and no less.
In the second picture the yā' is written small after the letter.$q$, 1, false, true, null, null, false
  from homeworks where number = 304;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 3, 'text', 'manual', $q$Madd with wāw. Read the following words and record yourself. Take your time, and hold each long vowel for two counts, no more and no less.
In the second picture the wāw is written small after the letter.$q$, 1, false, true, null, null, false
  from homeworks where number = 304;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 4, 'text', 'manual', $q$This exercise brings together everything we have covered so far, and is meant to push you. Please try your best. Read the following and record yourself.$q$, 1, false, true, null, null, false
  from homeworks where number = 304;

-- Audio needs questions.media (migration 0048); skipped until it exists.
do $media$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'questions' and column_name = 'media') then
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw4-1-1.jpg","alt":"Five words with madd by alif","width":640,"height":93},{"src":"/images/homework/qaidah/hw4-1-2.jpg","alt":"Twenty words with madd by alif","width":640,"height":374},{"src":"/images/homework/qaidah/hw4-1-3.jpg","alt":"Ten words with madd by a small alif written above the letter","width":640,"height":152}]}$q$::jsonb where position = 1 and homework_id = (select id from homeworks where number = 304);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw4-2-1.jpg","alt":"Forty words with madd by yā'","width":640,"height":738},{"src":"/images/homework/qaidah/hw4-2-2.jpg","alt":"Five words and phrases with madd by a small yā'","width":640,"height":164}]}$q$::jsonb where position = 2 and homework_id = (select id from homeworks where number = 304);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw4-3-1.jpg","alt":"Twenty-five words with madd by wāw","width":640,"height":411},{"src":"/images/homework/qaidah/hw4-3-2.jpg","alt":"Six words and phrases with madd by a small wāw","width":640,"height":147}]}$q$::jsonb where position = 3 and homework_id = (select id from homeworks where number = 304);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw4-4.jpg","alt":"Eighteen short phrases mixing the three letters of madd","width":640,"height":470}]}$q$::jsonb where position = 4 and homework_id = (select id from homeworks where number = 304);
  end if;
end $media$;

select number, title, total_marks, (select count(*) from questions q where q.homework_id = h.id) as questions
  from homeworks h where number in (304) order by number;
